CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE TYPE user_role AS ENUM ('admin','operator','viewer'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE device_status AS ENUM ('active','planned','offline','maintenance','decommissioned'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;

CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,email text NOT NULL UNIQUE,password_hash text NOT NULL,role user_role NOT NULL DEFAULT 'viewer',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions(user_id);
CREATE TABLE IF NOT EXISTS sites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text NOT NULL UNIQUE,description text NOT NULL DEFAULT '',address_line text,city text,state text,country text,postal_code text,latitude numeric(9,6) CHECK(latitude BETWEEN -90 AND 90),longitude numeric(9,6) CHECK(longitude BETWEEN -180 AND 180),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rooms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),site_id uuid NOT NULL REFERENCES sites ON DELETE CASCADE,name text NOT NULL,description text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(site_id,name));
CREATE TABLE IF NOT EXISTS racks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),site_id uuid NOT NULL REFERENCES sites ON DELETE CASCADE,room_id uuid REFERENCES rooms ON DELETE SET NULL,name text NOT NULL,description text NOT NULL DEFAULT '',rack_units int NOT NULL DEFAULT 42 CHECK(rack_units BETWEEN 1 AND 100),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(site_id,name));
CREATE TABLE IF NOT EXISTS manufacturers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,website text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS device_models (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),manufacturer_id uuid NOT NULL REFERENCES manufacturers,name text NOT NULL,height_u int NOT NULL DEFAULT 1 CHECK(height_u>0),default_port_count int,description text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(manufacturer_id,name));
CREATE TABLE IF NOT EXISTS devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,device_model_id uuid REFERENCES device_models ON DELETE SET NULL,manufacturer_id uuid REFERENCES manufacturers ON DELETE SET NULL,device_type text NOT NULL CHECK(device_type IN ('router','switch','server','firewall','olt','onu','storage','patch_panel','pdu','ups','wireless','rectifier','inverter','battery_bank','generator','transfer_switch','other')),site_id uuid NOT NULL REFERENCES sites ON DELETE RESTRICT,room_id uuid REFERENCES rooms ON DELETE SET NULL,rack_id uuid REFERENCES racks ON DELETE SET NULL,rack_position int,rack_height int NOT NULL DEFAULT 1 CHECK(rack_height>0),management_ip inet,serial_number text,asset_tag text,status device_status NOT NULL DEFAULT 'active',description text,power_supply_count int NOT NULL DEFAULT 1 CHECK(power_supply_count BETWEEN 0 AND 8),power_input_voltage text,power_capacity_watts int CHECK(power_capacity_watts IS NULL OR power_capacity_watts>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(site_id,name),CHECK((rack_id IS NULL AND rack_position IS NULL) OR (rack_id IS NOT NULL AND rack_position IS NOT NULL)));
CREATE INDEX IF NOT EXISTS devices_search_idx ON devices(name); CREATE INDEX IF NOT EXISTS devices_rack_idx ON devices(rack_id,rack_position);
CREATE OR REPLACE FUNCTION validate_rack_placement() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE units int; BEGIN IF NEW.rack_id IS NULL THEN RETURN NEW; END IF; SELECT rack_units INTO units FROM racks WHERE id=NEW.rack_id; IF NEW.rack_position<1 OR NEW.rack_position+NEW.rack_height-1>units THEN RAISE EXCEPTION 'device exceeds rack bounds'; END IF; IF EXISTS(SELECT 1 FROM devices d WHERE d.rack_id=NEW.rack_id AND d.id<>NEW.id AND int4range(d.rack_position,d.rack_position+d.rack_height,'[)') && int4range(NEW.rack_position,NEW.rack_position+NEW.rack_height,'[)')) THEN RAISE EXCEPTION 'rack position overlaps another device'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS devices_rack_collision ON devices; CREATE TRIGGER devices_rack_collision BEFORE INSERT OR UPDATE ON devices FOR EACH ROW EXECUTE FUNCTION validate_rack_placement();
CREATE TABLE IF NOT EXISTS device_ports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),device_id uuid NOT NULL REFERENCES devices ON DELETE CASCADE,name text NOT NULL,type text NOT NULL CHECK(type IN ('ethernet','fiber','sfp','sfp_plus','qsfp','console','power','wireless','other')),description text,speed text,enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(device_id,name));
CREATE TABLE IF NOT EXISTS cables (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),port_a_id uuid NOT NULL REFERENCES device_ports ON DELETE RESTRICT,port_b_id uuid NOT NULL REFERENCES device_ports ON DELETE RESTRICT,label text,cable_type text NOT NULL CHECK(cable_type IN ('cat5e','cat6','cat6a','dac','fiber_sm','fiber_mm','power','wireless','other')),color text,length numeric(8,2),description text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(port_a_id<>port_b_id),UNIQUE(port_a_id),UNIQUE(port_b_id));
CREATE OR REPLACE FUNCTION validate_cable_ports() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF EXISTS(SELECT 1 FROM cables WHERE id<>NEW.id AND (port_a_id IN(NEW.port_a_id,NEW.port_b_id) OR port_b_id IN(NEW.port_a_id,NEW.port_b_id))) THEN RAISE EXCEPTION 'port already has an active connection'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS cable_ports_unique ON cables; CREATE TRIGGER cable_ports_unique BEFORE INSERT OR UPDATE ON cables FOR EACH ROW EXECUTE FUNCTION validate_cable_ports();
CREATE TABLE IF NOT EXISTS networks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),site_id uuid REFERENCES sites ON DELETE SET NULL,prefix cidr NOT NULL UNIQUE,name text NOT NULL,description text,gateway inet,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ip_addresses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),network_id uuid REFERENCES networks ON DELETE SET NULL,address inet NOT NULL UNIQUE,device_id uuid REFERENCES devices ON DELETE SET NULL,port_id uuid REFERENCES device_ports ON DELETE SET NULL,dns_name text,description text,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','reserved','available','deprecated')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE devices ADD COLUMN IF NOT EXISTS management_ip_address_id uuid REFERENCES ip_addresses(id) ON DELETE SET NULL;
CREATE TABLE IF NOT EXISTS vlans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),site_id uuid REFERENCES sites ON DELETE CASCADE,vid int NOT NULL CHECK(vid BETWEEN 1 AND 4094),name text NOT NULL,description text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(site_id,vid));
CREATE TABLE IF NOT EXISTS vlan_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),port_id uuid NOT NULL REFERENCES device_ports ON DELETE CASCADE,vlan_id uuid NOT NULL REFERENCES vlans ON DELETE CASCADE,mode text NOT NULL CHECK(mode IN ('access','tagged','native')),UNIQUE(port_id,vlan_id));
CREATE TABLE IF NOT EXISTS tags (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE); CREATE TABLE IF NOT EXISTS device_tags (device_id uuid REFERENCES devices ON DELETE CASCADE,tag_id uuid REFERENCES tags ON DELETE CASCADE,PRIMARY KEY(device_id,tag_id));
